    vatertag: ['Festa del papà', 'Papà re della griglia', 'La griglia stampata prende vita: le salsicce sul biglietto sfrigolano dal vivo, si girano al momento dorato e volano nel piatto stampato.'],
    einhorn: ['Compleanno bambini', 'Acchiappastelle', 'Un unicorno sotto sei stelle dorate. Alla scansione le stelle stampate si accendono una a una – toccale in fretta e volano sul corno in un lampo arcobaleno.'],
    papa: ['Compleanno / Per papà', 'Muro di tiro per papà', 'Un muro di tiro sotto i riflettori. Alla scansione il pallone stampato si anima: sei tiri con uno swipe nei buchi stampati – con il boato dello stadio.'],
    mama: ['Compleanno / Per la mamma', 'Con amore, mamma', 'Un\'aiuola rigogliosa con un annaffiatoio di rame. Alla scansione i fiori stampati hanno sete – l\'annaffiatoio stampato segue il dito e fa brillare ogni fiore.'],
    partyturm: ['Compleanno divertente', 'Evviva!', 'Una torre di regali colorata su un tavolo da festa. Alla scansione i pacchi stampati volano via coi palloncini – falli ricadere precisi al loro posto.'],
    kaetzchen: ['Per te / Generale', 'Gattino con palla', 'Il gattino lancia la palla fuori dal biglietto – rilanciala e continua a giocare felice.'],
    max: ['Compleanno / Baviera', 'Gioco dell\'Oktoberfest', 'Prendi brezel, birra e cuori con il boccale – il cuore di pan di zenzero porta il tuo nome.'],
    torte: ['Compleanno', 'Spegni le candeline', 'La torta gira – spegni tutte le candeline prima che scada il tempo. Poi coriandoli e «Buon compleanno».'],
    ballons: ['Compleanno / Bambini', 'Scoppia i palloncini', '20 secondi per scoppiare palloncini, quelli dorati valgono il triplo.'],
    rubbellos: ['Buono / Regalo', 'Gratta e vinci', 'Gratta il campo – sotto si nasconde il regalo personale.'],
    weihnacht: ['Natale', 'Villaggio innevato', 'Toccando nevica, al quinto tocco l\'albero si illumina – con Jingle Bells.'],
    liebe: ['Amore / San Valentino', 'La lettera d\'amore', 'Tocca il sigillo – la lettera si apre, piovono petali, il messaggio si scrive da solo.'],
    baby: ['Nascita / Battesimo', 'Benvenuto, piccolo tesoro', 'Sposta le nuvole – compaiono nome, data e peso, con una ninna nanna.'],
    feuerwerk: ['Capodanno / Successo / Anniversario', 'Accendi i fuochi', 'Ogni tocco un razzo, dopo otto il gran finale.'],
    weltraum: ['Bambini / Compleanno', 'Missione spaziale', 'Guida l\'astronave, abbatti meteoriti, raccogli stelle – ogni stella potenzia l\'arma. Tre vite.'],
    blume: ['Grazie / Festa della mamma / Conforto', 'La rosa sboccia', 'Tocca il bocciolo – la rosa sboccia, farfalle e un messaggio.'],
    gluecksrad: ['Buono / Compleanno', 'Ruota della fortuna', 'Gira la ruota – i premi li sceglie chi regala.'],
